from pathlib import Path

ROOT = Path.cwd()
BROWSER = ROOT / 'components/characters/character-inventory-browser.tsx'
DISPLAY = ROOT / 'components/characters/character-inventory-display.tsx'

if not (ROOT / 'package.json').exists():
    raise SystemExit('ERROR: Run this from the sepulchria-portal repository root.')

browser = BROWSER.read_text(encoding='utf-8')
display = DISPLAY.read_text(encoding='utf-8')

def rep(text, old, new, label):
    if old not in text:
        raise SystemExit(f'ERROR: Could not find {label}.')
    return text.replace(old, new, 1)

if 'InventoryEquipmentBonus' not in browser:
    browser = rep(browser, 'export type InventoryRequirement = {\n  label: string;\n  met: boolean;\n};\n\n', 'export type InventoryRequirement = {\n  label: string;\n  met: boolean;\n};\n\nexport type InventoryEquipmentBonus = {\n  label: string;\n  value: number;\n};\n\n', 'InventoryRequirement type')
if 'InventoryEquipmentBonus' not in browser:
    browser = rep(browser, '  requirements:\n    InventoryRequirement[];\n};\n', '  requirements:\n    InventoryRequirement[];\n  equipment_bonuses:\n    InventoryEquipmentBonus[];\n};\n', 'InventoryBrowserRow requirements')

start = browser.find('function EquipmentSlotCard({')
end = browser.find('\nconst DESKTOP_POSITIONS:', start)
if start == -1 or end == -1:
    raise SystemExit('ERROR: EquipmentSlotCard block not found.')
browser = browser[:start] + 'function EquipmentCandidate({\n  row,\n}: {\n  row: InventoryBrowserRow;\n}) {\n  const eligible =\n    meetsAllRequirements(row);\n\n  return (\n    <div className="mt-2 border-t border-[#59432c]/30 pt-2">\n      <div className="flex gap-2">\n        <ItemThumbnail row={row} size="small" />\n\n        <div className="min-w-0 flex-1">\n          <p className="font-serif text-[12px] text-[#d8c095]">\n            {row.name}\n          </p>\n\n          {row.description?.trim() ? (\n            <p className="mt-1 line-clamp-3 text-[8px] leading-4 text-[#8f8271]">\n              {row.description}\n            </p>\n          ) : null}\n        </div>\n      </div>\n\n      {row.equipment_bonuses.length ? (\n        <div className="mt-2 border-t border-[#59432c]/25 pt-2">\n          <p className="text-[7px] uppercase tracking-[0.14em] text-[#806b50]">\n            Bonuses\n          </p>\n\n          <div className="mt-1.5 flex flex-wrap gap-1.5">\n            {row.equipment_bonuses.map((bonus) => (\n              <span\n                key={bonus.label}\n                className="border border-[#49634f]/55 bg-[#132016] px-2 py-1 text-[7px] uppercase tracking-[0.1em] text-[#9cbe9f]"\n              >\n                {bonus.label} {bonus.value > 0 ? "+" : ""}\n                {bonus.value}\n              </span>\n            ))}\n          </div>\n        </div>\n      ) : null}\n\n      <Requirements requirements={row.requirements} />\n\n      {eligible ? (\n        <form action={equipInventoryItem} className="mt-2">\n          <input type="hidden" name="recordKind" value={row.record_kind} />\n          <input type="hidden" name="recordId" value={row.record_id} />\n\n          <button\n            type="submit"\n            className="w-full border border-[#987344] bg-[#3b2919] px-3 py-2 text-[8px] uppercase tracking-[0.14em] text-[#efd6a8] transition hover:bg-[#4a321e]"\n          >\n            Equip\n          </button>\n        </form>\n      ) : (\n        <p className="mt-2 border border-red-900/45 bg-red-950/10 px-2 py-2 text-[7px] uppercase tracking-[0.1em] text-red-400">\n          Requirements not met\n        </p>\n      )}\n    </div>\n  );\n}\n\nfunction EquipmentSlotCard({\n  slot,\n  rows,\n  available,\n  own,\n}: {\n  slot: string;\n  rows: InventoryBrowserRow[];\n  available: InventoryBrowserRow[];\n  own: boolean;\n}) {\n  const [open, setOpen] = useState(false);\n  const [selectedId, setSelectedId] = useState("");\n\n  const sorted = [...rows].sort(\n    (a, b) =>\n      LAYER_ORDER.indexOf(\n        a.equipped_layer as (typeof LAYER_ORDER)[number],\n      ) -\n      LAYER_ORDER.indexOf(\n        b.equipped_layer as (typeof LAYER_ORDER)[number],\n      ),\n  );\n\n  const selected =\n    available.find(\n      (row) =>\n        `${row.record_kind}:${row.record_id}` === selectedId,\n    ) ?? null;\n\n  return (\n    <div className="border border-[#60482e]/45 bg-[#120d09]/95 p-2.5 shadow-[0_8px_24px_rgba(0,0,0,0.18)]">\n      <p className="text-[7px] uppercase tracking-[0.18em] text-[#876f4f]">\n        {SLOT_LABELS[slot]}\n      </p>\n\n      {sorted.length ? (\n        <div className="mt-2 space-y-2">\n          {sorted.map((row) => (\n            <div\n              key={`${row.record_kind}-${row.record_id}`}\n              className="flex items-center gap-2 border-t border-[#59432c]/25 pt-2 first:border-t-0 first:pt-0"\n            >\n              <ItemThumbnail row={row} size="small" />\n\n              <div className="min-w-0 flex-1">\n                <p className="truncate font-serif text-[12px] text-[#d8c095]">\n                  {row.name}\n                </p>\n                <p className="mt-0.5 text-[6px] uppercase tracking-[0.12em] text-[#756957]">\n                  {titleCase(row.equipped_layer ?? "equipped")}\n                </p>\n              </div>\n\n              {own ? (\n                <form action={unequipInventoryItem}>\n                  <input type="hidden" name="recordKind" value={row.record_kind} />\n                  <input type="hidden" name="recordId" value={row.record_id} />\n                  <button\n                    type="submit"\n                    title={`Unequip ${row.name}`}\n                    className="px-1 text-[13px] text-[#806d55] transition hover:text-[#d7b77f]"\n                  >\n                    ×\n                  </button>\n                </form>\n              ) : null}\n            </div>\n          ))}\n        </div>\n      ) : own ? (\n        <div className="mt-2">\n          <button\n            type="button"\n            onClick={() => setOpen((value) => !value)}\n            className="w-full border border-dashed border-[#6d5336]/55 bg-[#17110d] px-3 py-3 text-left transition hover:border-[#9b7548] hover:bg-[#1c140e]"\n          >\n            <span className="block text-[9px] uppercase tracking-[0.14em] text-[#947c5b]">\n              Empty\n            </span>\n            <span className="mt-1 block text-[7px] uppercase tracking-[0.12em] text-[#665b4c]">\n              Click to equip\n            </span>\n          </button>\n\n          {open ? (\n            <div className="mt-2 border border-[#60482e]/40 bg-[#0e0a08] p-2">\n              {available.length ? (\n                <>\n                  <select\n                    value={selectedId}\n                    onChange={(event) => setSelectedId(event.target.value)}\n                    className="w-full border border-[#60482e]/55 bg-[#100c09] px-2 py-2 text-[9px] text-[#cdb894] outline-none focus:border-[#987344]"\n                  >\n                    <option value="">Choose Item...</option>\n                    {available.map((row) => (\n                      <option\n                        key={`${row.record_kind}:${row.record_id}`}\n                        value={`${row.record_kind}:${row.record_id}`}\n                      >\n                        {row.name}\n                        {row.quantity > 1 ? ` ×${row.quantity}` : ""}\n                      </option>\n                    ))}\n                  </select>\n\n                  {selected ? <EquipmentCandidate row={selected} /> : null}\n                </>\n              ) : (\n                <p className="text-[8px] italic leading-4 text-[#665b4c]">\n                  No available Items for this slot.\n                </p>\n              )}\n            </div>\n          ) : null}\n        </div>\n      ) : (\n        <p className="mt-2 text-[9px] italic text-[#665b4c]">\n          Empty\n        </p>\n      )}\n    </div>\n  );\n}\n' + browser[end:]

browser = rep(browser, 'function EquipmentFigure({\n  equipped,\n  own,\n}: {\n  equipped:\n    InventoryBrowserRow[];\n  own: boolean;\n}) {\n', 'function EquipmentFigure({\n  equipped,\n  inventory,\n  own,\n}: {\n  equipped:\n    InventoryBrowserRow[];\n  inventory:\n    InventoryBrowserRow[];\n  own: boolean;\n}) {\n', 'EquipmentFigure signature')
browser = rep(browser, '  for (const row of equipped) {\n    if (!row.equipped_slot) {\n      continue;\n    }\n\n    const values =\n      bySlot.get(\n        row.equipped_slot,\n      ) ?? [];\n\n    values.push(row);\n\n    bySlot.set(\n      row.equipped_slot,\n      values,\n    );\n  }\n\n  return (\n', '  for (const row of equipped) {\n    if (!row.equipped_slot) {\n      continue;\n    }\n\n    const values =\n      bySlot.get(\n        row.equipped_slot,\n      ) ?? [];\n\n    values.push(row);\n\n    bySlot.set(\n      row.equipped_slot,\n      values,\n    );\n  }\n\n  const availableBySlot =\n    new Map<\n      string,\n      InventoryBrowserRow[]\n    >();\n\n  for (const row of inventory) {\n    if (\n      !row.is_equippable ||\n      row.is_equipped ||\n      row.parent_container_id ||\n      !row.configured_slot\n    ) {\n      continue;\n    }\n\n    const values =\n      availableBySlot.get(\n        row.configured_slot,\n      ) ?? [];\n\n    values.push(row);\n\n    availableBySlot.set(\n      row.configured_slot,\n      values,\n    );\n  }\n\n  return (\n', 'EquipmentFigure available slots')
browser = rep(browser, '      <EquipmentFigure\n        equipped={\n          equipped\n        }\n        own={own}\n      />\n', '      <EquipmentFigure\n        equipped={\n          equipped\n        }\n        inventory={rows}\n        own={own}\n      />\n', 'EquipmentFigure render')
browser = rep(browser, '              <EquipmentSlotCard\n                slot={slot}\n                rows={\n                  bySlot.get(\n                    slot,\n                  ) ?? []\n                }\n                own={own}\n              />\n', '              <EquipmentSlotCard\n                slot={slot}\n                rows={\n                  bySlot.get(\n                    slot,\n                  ) ?? []\n                }\n                available={\n                  availableBySlot.get(\n                    slot,\n                  ) ?? []\n                }\n                own={own}\n              />\n', 'desktop EquipmentSlotCard')
browser = rep(browser, '            <EquipmentSlotCard\n              key={slot}\n              slot={slot}\n              rows={\n                bySlot.get(\n                  slot,\n                ) ?? []\n              }\n              own={own}\n            />\n', '            <EquipmentSlotCard\n              key={slot}\n              slot={slot}\n              rows={\n                bySlot.get(\n                  slot,\n                ) ?? []\n              }\n              available={\n                availableBySlot.get(\n                  slot,\n                ) ?? []\n              }\n              own={own}\n            />\n', 'mobile EquipmentSlotCard')

display = rep(display, '    | {\n        trigger_type: string;\n        effect_mode: string;\n        health_delta: number;\n      }[]\n', '    | {\n        trigger_type: string;\n        effect_mode: string;\n        health_delta: number;\n        muscles_modifier: number;\n        reflexes_modifier: number;\n        vigour_modifier: number;\n        shrewd_modifier: number;\n        brains_modifier: number;\n        presence_modifier: number;\n        max_health_modifier: number;\n      }[]\n', 'item effect type')
display = rep(display, '            effects:item_effects(\n              trigger_type,\n              effect_mode,\n              health_delta\n            ),\n', '            effects:item_effects(\n              trigger_type,\n              effect_mode,\n              health_delta,\n              muscles_modifier,\n              reflexes_modifier,\n              vigour_modifier,\n              shrewd_modifier,\n              brains_modifier,\n              presence_modifier,\n              max_health_modifier\n            ),\n', 'item effect query')
if 'function equipmentBonuses(' not in display:
    display = rep(display, 'export async function CharacterInventoryDisplay({\\n', 'function equipmentBonuses(\n  item: ItemRequirementRow | undefined,\n) {\n  if (!item) {\n    return [];\n  }\n\n  const totals =\n    new Map<string, number>();\n\n  const add = (\n    label: string,\n    value: number,\n  ) => {\n    if (!value) {\n      return;\n    }\n\n    totals.set(\n      label,\n      (totals.get(label) ?? 0) +\n        value,\n    );\n  };\n\n  for (const effect of item.effects ?? []) {\n    if (\n      effect.trigger_type !==\n      "passive"\n    ) {\n      continue;\n    }\n\n    add("Muscles", effect.muscles_modifier);\n    add("Reflexes", effect.reflexes_modifier);\n    add("Vigour", effect.vigour_modifier);\n    add("Shrewd", effect.shrewd_modifier);\n    add("Brains", effect.brains_modifier);\n    add("Presence", effect.presence_modifier);\n    add("Max Health", effect.max_health_modifier);\n  }\n\n  return [...totals.entries()]\n    .filter(([, value]) => value !== 0)\n    .map(([label, value]) => ({\n      label,\n      value,\n    }));\n}\n\nexport async function CharacterInventoryDisplay({\\n', 'CharacterInventoryDisplay declaration')
display = rep(display, '        requirements:\n          row.is_equippable\n            ? requirementList(\n                master,\n                character,\n                membership,\n              )\n            : [],\n      };\n', '        requirements:\n          row.is_equippable\n            ? requirementList(\n                master,\n                character,\n                membership,\n              )\n            : [],\n        equipment_bonuses:\n          row.is_equippable\n            ? equipmentBonuses(\n                master,\n              )\n            : [],\n      };\n', 'browser row mapping')

BROWSER.write_text(browser, encoding='utf-8')
DISPLAY.write_text(display, encoding='utf-8')

print('SUCCESS')
print('Clickable Equipment slot picker installed.')
print('No SQL required.')
print('Now run: npm run build')